#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;       // read caller's x through a
    *a = *b;          // write caller's x
    *b = t;           // write caller's y
}

int main(void) {
    int x = 3, y = 7;
    int *p = &x;                      // p holds the address of x
    printf("%d %p\n", *p, (void *)p); // 3 and an address like 0x7ffc...
    swap(&x, &y);                     // pass addresses
    printf("%d %d\n", x, y);          // 7 3
    printf("%zu %zu\n", sizeof p, sizeof *p);   // 8 4
    return 0;
}

int *a; char *b; double *c;
printf("%zu %zu %zu\n", sizeof a, sizeof b, sizeof c);  // 8 8 8
printf("%p\n", (void *)&a);    // for example 0x7ffd8a3e1c28

void alloc_int(int **out, int v) {      // changes the caller's pointer
    *out = malloc(sizeof **out);
    if (*out) **out = v;
}
struct node { int v; struct node *next; };
void push(struct node **head, int v) {  // insert at head
    struct node *n = malloc(sizeof *n);
    if (!n) return;
    n->v = v; n->next = *head; *head = n;
}

int var = 10, *p = &var, **pp = &p;
printf("%d %d %d\n", var, *p, **pp);   // 10 10 10
**pp = 99;                              // var is now 99

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int (*ops[])(int, int) = { add, sub };
printf("%d %d\n", ops[0](10, 5), ops[1](10, 5));   // 15 5

struct node { int v; struct node *next; };
void free_list(struct node *h) {
    while (h) { struct node *nx = h->next; free(h); h = nx; }
}
